<?php
require_once __DIR__ . '/../include/session.php';require_once __DIR__ . '/../include/config.php';if(empty($_SESSION['user'])){header('Location: '.BASE_URL.'/index.php');exit;}
$type=trim((string)($_GET['jenis']??''));if(!in_array($type,['Masuk','Keluar'],true))$type='';$q=trim((string)($_GET['q']??''));$like='%'.$q.'%';$status=trim((string)($_GET['status']??''));$from=trim((string)($_GET['from']??''));$to=trim((string)($_GET['to']??''));$archive=($_GET['arsip']??'')==='1';$year=trim((string)($_GET['tahun']??''));if(!preg_match('/^20\d{2}$/',$year))$year='';
if($archive){$stmt=$conn->prepare("SELECT s.nomor_surat,s.jenis_surat,s.tanggal_surat,s.tanggal_diterima,s.pengirim,s.tujuan,s.perihal,s.status,a.tahun_arsip,a.archived_at FROM arsip_surat a JOIN surat s ON s.id=a.surat_id WHERE s.status='Selesai' AND (?='' OR s.jenis_surat=?) AND (?='' OR s.nomor_surat LIKE ? OR s.perihal LIKE ? OR s.pengirim LIKE ? OR s.tujuan LIKE ?) AND (?='' OR a.tahun_arsip=?) ORDER BY a.archived_at DESC");$stmt->bind_param('sssssssss',$type,$type,$q,$like,$like,$like,$like,$year,$year);}else{$dateCol=$type==='Masuk'?'tanggal_diterima':'tanggal_surat';$from=trim((string)($_GET['from']??''));$to=trim((string)($_GET['to']??''));if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$from)||!checkdate((int)substr($from,5,2),(int)substr($from,8,2),(int)substr($from,0,4)))$from='';if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$to)||!checkdate((int)substr($to,5,2),(int)substr($to,8,2),(int)substr($to,0,4)))$to='';$stmt=$conn->prepare("SELECT nomor_surat,jenis_surat,tanggal_surat,tanggal_diterima,pengirim,tujuan,perihal,status,created_at FROM surat WHERE (?='' OR jenis_surat=?) AND (?='' OR nomor_surat LIKE ? OR perihal LIKE ? OR pengirim LIKE ? OR tujuan LIKE ?) AND (?='' OR status=?) AND (?='' OR {$dateCol}>=?) AND (?='' OR {$dateCol}<=?) ORDER BY created_at DESC");$stmt->bind_param('sssssssssssss',$type,$type,$q,$like,$like,$like,$like,$status,$status,$from,$from,$to,$to);}
$stmt->execute();$rows=$stmt->get_result();header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="'.($archive?'arsip-surat':'data-surat').'-'.date('Ymd-His').'.csv"');$out=fopen('php://output','w');fwrite($out,"\xEF\xBB\xBF");if($archive){fputcsv($out,['Nomor Surat','Jenis','Tanggal Surat','Tanggal Diterima','Pengirim','Tujuan','Perihal','Status','Tahun Arsip','Tanggal Arsip']);}else{fputcsv($out,['Nomor Surat','Jenis','Tanggal Surat','Tanggal Diterima','Pengirim','Tujuan','Perihal','Status','Tanggal Dicatat']);}
while($row=$rows->fetch_assoc()){$values=array_values($row);foreach($values as &$value){$value=(string)$value;if($value!==''&&preg_match('/^[=+\-@\t\r]/',$value))$value="'".$value;}unset($value);fputcsv($out,$values);}fclose($out);exit;
